"""
Pydantic schemas for device API responses.
"""

from __future__ import annotations

from datetime import datetime
from decimal import Decimal
from enum import Enum
from typing import TYPE_CHECKING, Any, Literal, Optional, Union

from pydantic import BaseModel, ConfigDict, Field, field_serializer, field_validator

from qbraid_core.decimal import Credits

from .enums import DeviceStatus, ExperimentType

if TYPE_CHECKING:
    from bson.objectid import ObjectId


class DevicePricing(BaseModel):
    """Represents pricing information for a quantum device."""

    model_config = ConfigDict(frozen=True)

    perTask: Credits
    perShot: Credits
    perMinute: Credits

    @field_serializer("perTask", "perShot", "perMinute")
    def serialize_credits(self, value: Credits) -> float:
        """Serialize Credits objects to float for JSON response."""
        return float(value)

    def calculate_cost(
        self,
        num_tasks: int,
        num_minutes: Optional[Union[int, float]] = None,
        num_shots: Optional[int] = None,
    ) -> Credits:
        """Calculate the total cost for a job based on pricing.

        Args:
            num_tasks (int): Number of tasks to execute.
            num_minutes (int | float | None): Number of minutes the job will run
            num_shots (int | None): Number of shots the job will execute.

        Returns:
            Total cost in credits

        Raises:
            ValueError: If both num_minutes and num_shots are None,
                or if any value is negative.
        """
        if num_tasks < 0:
            raise ValueError("num_tasks must be greater than or equal to 0")

        if num_minutes is None and num_shots is None:
            raise ValueError("At least one of num_minutes or num_shots must be provided")

        if num_minutes is not None and num_minutes < 0:
            raise ValueError("num_minutes must be greater than or equal to 0")

        if num_shots is not None and num_shots < 0:
            raise ValueError("num_shots must be greater than or equal to 0")

        num_minutes = num_minutes or 0
        num_shots = num_shots or 0

        # Use Decimal arithmetic to avoid floating point precision errors
        # Convert inputs to Decimal for consistent arithmetic
        num_tasks_decimal = Decimal(str(num_tasks))
        num_shots_decimal = Decimal(str(num_shots))
        num_minutes_decimal = Decimal(str(num_minutes))

        # Credits is a subclass of Decimal, so we can do Decimal arithmetic directly
        total_cost = (
            (num_tasks_decimal * Decimal(self.perTask))
            + (num_shots_decimal * Decimal(self.perShot))
            + (num_minutes_decimal * Decimal(self.perMinute))
        )
        return Credits(total_cost)


class RuntimeDevice(BaseModel):
    """Schema for device response.

    Note: vendor and deviceType are intentionally typed as `str` rather than
    Literal[...] so that newly added providers/device types from the API don't
    break the entire list_devices() call. The frontend can handle unknown
    values gracefully; failing validation here means losing ALL devices.
    """

    # Allow unknown extra fields from the API without breaking validation
    model_config = ConfigDict(extra="ignore")

    name: str
    qrn: str
    vendor: str
    deviceType: str
    runInputTypes: list[str]
    status: DeviceStatus
    statusMsg: Optional[str] = None
    nextAvailable: Optional[datetime] = None
    queueDepth: Optional[int] = None
    avgQueueTime: Optional[int] = None  # in minutes
    numberQubits: Optional[int] = None
    paradigm: ExperimentType
    modality: Optional[str] = None  # only applies to QPUs
    noiseModels: Optional[list[str]] = None  # only applies to simulators
    minShots: Optional[int] = None
    maxShots: Optional[int] = None
    pricingModel: Optional[str] = None  # None if direct access is False
    pricing: Optional[DevicePricing] = None  # only applies to fixed pricing model
    directAccess: bool = True
    batchJobSupport: bool = False
    topology: Optional[dict[str, Any]] = None


class DeviceVerification(Enum):
    """Enumeration for representing various verification statuses of devices.

    Attributes:
        VERIFIED (str): Device has been verified.
        UNVERIFIED (str): Device has not been verified.
        PENDING (str): Device verification is pending.
        FAILED (str): Device verification has failed.
    """

    VERIFIED = "verified"
    UNVERIFIED = "unverified"
    PENDING = "pending"
    FAILED = "failed"


class PlatformDevice(RuntimeDevice):
    """Schema for platform device model with extended fields."""

    vrn: str
    providerId: str
    visibility: Literal["public", "private"]
    verified: DeviceVerification
    requestedBy: Optional[str] = None
    pendingEdits: Optional[Any] = None
    image: Optional[str] = None
    description: Optional[str] = None
    activeVersion: Optional[str] = None
    whiteListedDomains: Optional[list[str]] = None
    blackListedDomains: Optional[list[str]] = None
    notes: Optional[str] = None
    statusLocked: bool = False

    @field_validator("providerId", mode="before")
    @classmethod
    def validate_provider_id(cls, value) -> str:
        """Ensures that the provider id is a string."""
        return str(value)


class ProviderLogo(BaseModel):
    """Logo URLs for a provider."""

    model_config = ConfigDict(extra="ignore")

    light: Optional[str] = None
    dark: Optional[str] = None


class RuntimeProvider(BaseModel):
    """Schema for provider response from GET /providers."""

    model_config = ConfigDict(extra="ignore", populate_by_name=True)

    id: str
    provider: str
    providerDescription: Optional[str] = None
    about: Optional[str] = None
    visibility: Optional[str] = None
    devices: list[str] = []
    logo: Optional[ProviderLogo] = None
    qrn: Optional[str] = None


class EdgeEntry(BaseModel):
    """Single two-qubit gate calibration measurement."""

    model_config = ConfigDict(extra="ignore")

    source: int
    target: int
    value: float


class QubitCalibration(BaseModel):
    """Per-qubit calibration metrics."""

    model_config = ConfigDict(extra="ignore", populate_by_name=True)

    t1: Optional[float] = None
    t2: Optional[float] = None
    frequency: Optional[float] = None
    readout_error: Optional[float] = Field(None, alias="readoutError")
    gate_error: Optional[dict[str, float]] = Field(None, alias="gateError")


class DeviceCalibration(BaseModel):
    """Device calibration snapshot."""

    model_config = ConfigDict(extra="ignore", populate_by_name=True)

    physical_device_id: str = Field(alias="physicalDeviceId")
    device_qrns: list[str] = Field(alias="deviceQRNs")
    provider: str
    last_calibrated: str = Field(alias="lastCalibrated")
    fetched_at: str = Field(alias="fetchedAt")
    qubits: dict[str, QubitCalibration]
    edges: dict[str, dict[str, list[EdgeEntry]]]
